457 |                     ? fn.arguments.slice(0, 200) + '...'
458 |                     : fn.arguments;
459 |                 const parseErrorMsg = parseError instanceof Error ? parseError.message : String(parseError);
460 |                 const errorMsg = `Invalid JSON in tool parameters: ${parseErrorMsg}\nReceived: ${truncatedArgs}`;
461 | 
462 |                 await this.eventBus.emit('agent.tool.params.parse.error', {
463 |                     toolName: fn.name,
464 |                     rawArguments: fn.arguments,
465 |                     error: new Error(errorMsg),
466 |                     toolCallId: id,
467 |                 });
468 | 
469 |                 this.logger.error(errorMsg);
470 |                 return {
471 |                     toolCall,
472 |                     result: `Error: Failed to parse tool arguments. The JSON was malformed. Please try again with properly formatted parameters.`,
473 |                     error: errorMsg,
474 |                 };
475 |             }
476 | 
477 |             const spinner = this.logger.spinner(`Tool ${fn.name}(...)`);
478 | 
479 |             let result: string;
480 |             try {
481 |                 result = await this.withTimeout(
482 |                     ToolRegistry.execute(fn.name, args),
483 |                     this.toolTimeoutMs,
