501 |                 toolName: fn.name,
502 |                 result,
503 |                 duration: toolDuration,
504 |                 toolCallId: id,
505 |                 iteration,
506 |             });
507 | 
508 |             await this.eventBus.emit('agent.tool.call.complete', {
509 |                 toolName: fn.name,
510 |                 result,
511 |                 duration: toolDuration,
512 |                 toolCallId: id,
513 |                 iteration,
514 |             });
515 | 
516 |             return { toolCall, result, error: undefined };
517 |         } catch (error) {
518 |             const errorMsg = error instanceof Error ? error.message : String(error);
519 | 
520 |             await this.triggerHook(AgentHook.ON_TOOL_ERROR, {
521 |                 toolName: fn.name,
522 |                 error: error instanceof Error ? error : new Error(errorMsg),
523 |                 params: fn.arguments,
524 |                 toolCallId: id,
525 |                 iteration,
