349 | export class CacheHookPlugin implements HookPlugin {
350 |     private cache = new Map<string, any>();
351 |     private logger: ScopedLogger;
352 |     private ttl: number; // 缓存存活时间（毫秒）
353 | 
354 |     constructor(loggerName = 'CacheHook', ttl = 5 * 60 * 1000) { // 默认5分钟
355 |         this.logger = new ScopedLogger(loggerName);
356 |         this.ttl = ttl;
357 |     }
358 | 
359 |     /**
360 |      * 注册缓存钩子
361 |      */
362 |     registerAllHooks(agent: HookAgent): HookRegistration[] {
363 |         const registrations: HookRegistration[] = [];
364 |         const register = <T>(
365 |             hook: AgentHook,
366 |             handler: (_data: T) => void | Promise<void>,
367 |             config?: AgentHookConfig
368 |         ) => {
369 |             const handlerId = agent.registerHook(hook, handler, config);
370 |             registrations.push({ hook, handlerId });
371 |         };
372 | 
373 |         // LLM 响应缓存
374 |         register(AgentHook.BEFORE_LLM_CALL, async (data: BeforeLLMCallData) => {
375 |                 const cacheKey = this.generateLLMCacheKey(data);
