378 |                 if (cached && Date.now() - cached.timestamp < this.ttl) {
379 |                     this.logger.debug(`Cache hit for LLM call: ${cacheKey}`);
380 |                     // 这里可以返回缓存的响应，但需要修改 Agent 流程
381 |                     // 目前只记录命中率
382 |                 }
383 |             }, { priority: 15, async: true });
384 | 
385 |         register(AgentHook.AFTER_LLM_CALL, (data: AfterLLMCallData) => {
386 |                 const cacheKey = this.generateLLMCacheKey(data);
387 |                 this.cache.set(cacheKey, {
388 |                     response: data.response,
389 |                     timestamp: Date.now(),
390 |                 });
391 |                 this.logger.debug(`Cached LLM response: ${cacheKey}`);
392 |             }, { priority: 85 });
393 | 
394 |         // 工具结果缓存
395 |         register(AgentHook.BEFORE_TOOL_CALL, async (data: BeforeToolCallData) => {
396 |                 const cacheKey = this.generateToolCacheKey(data);
397 |                 const cached = this.cache.get(cacheKey);
398 |                 
399 |                 if (cached && Date.now() - cached.timestamp < this.ttl) {
400 |                     this.logger.debug(`Cache hit for tool: ${data.toolName}`);
401 |                     // 这里可以返回缓存的结果
402 |                 }
403 |             }, { priority: 35, async: true });
404 | 
405 |         register(AgentHook.AFTER_TOOL_CALL, (data: AfterToolCallData) => {
406 |                 const cacheKey = this.generateToolCacheKey(data);
407 |                 this.cache.set(cacheKey, {
408 |                     result: data.result,
409 |                     timestamp: Date.now(),
410 |                 });
411 |                 this.logger.debug(`Cached tool result: ${data.toolName}`);
412 |             }, { priority: 65 });
413 | 
414 |         return registrations;
415 |     }
416 | 
417 |     private generateLLMCacheKey(data: BeforeLLMCallData | AfterLLMCallData): string {
418 |         return `llm:${data.model}:${JSON.stringify(data.prompt)}:${JSON.stringify(data.tools || [])}`;
419 |     }
420 | 
421 |     private generateToolCacheKey(data: BeforeToolCallData | AfterToolCallData): string {
422 |         // AfterToolCallData 没有 params 属性，使用 toolName 和 result 生成键
423 |         const params = 'params' in data ? data.params : {};
424 |         return `tool:${data.toolName}:${JSON.stringify(params)}`;
425 |     }
426 | 
427 |     /**
428 |      * 获取缓存统计
429 |      */
430 |     getCacheStats() {
431 |         return {
432 |             size: this.cache.size,
433 |             keys: Array.from(this.cache.keys()),
434 |         };
435 |     }
436 | 
437 |     /**
438 |      * 清空缓存
439 |      */
440 |     clearCache() {
441 |         this.cache.clear();
442 |         this.logger.info('Cache cleared');
443 |     }
444 | }
