446 | /**
447 |  * 钩子管理器
448 |  * 方便地管理多个钩子插件
449 |  */
450 | export class HookManager {
451 |     private plugins = new Map<string, HookPlugin>();
452 |     private registeredHandlers = new Map<string, HookRegistration[]>();
453 |     private logger: ScopedLogger;
454 | 
455 |     constructor(loggerName = 'HookManager') {
456 |         this.logger = new ScopedLogger(loggerName);
457 |     }
458 | 
459 |     /**
460 |      * 注册插件
461 |      */
462 |     registerPlugin(name: string, plugin: HookPlugin, agent: HookAgent): void {
463 |         if (this.plugins.has(name)) {
464 |             this.logger.warn(`Plugin ${name} already registered, replacing`);
465 |             this.unregisterPlugin(name, agent);
466 |         }
467 | 
468 |         this.plugins.set(name, plugin);
469 |         
470 |         // 注册插件的所有钩子
471 |         if (plugin.registerAllHooks) {
472 |             const registrations = plugin.registerAllHooks(agent);
473 |             this.registeredHandlers.set(name, registrations);
474 |             this.logger.info(`Registered plugin ${name} with ${registrations.length} handlers`);
475 |         }
476 |     }
477 | 
478 |     /**
479 |      * 移除插件
480 |      */
481 |     unregisterPlugin(name: string, agent: HookAgent): boolean {
482 |         const plugin = this.plugins.get(name);
483 |         if (!plugin) return false;
484 | 
485 |         // 移除插件的所有钩子
486 |         const registrations = this.registeredHandlers.get(name) || [];
487 |         if (agent.unregisterHook) {
488 |             for (const registration of registrations) {
489 |                 agent.unregisterHook(registration.hook, registration.handlerId);
490 |             }
491 |         }
492 | 
493 |         this.plugins.delete(name);
494 |         this.registeredHandlers.delete(name);
495 |         this.logger.info(`Unregistered plugin ${name}`);
496 | 
497 |         return true;
498 |     }
499 | 
500 |     /**
501 |      * 获取所有插件
502 |      */
503 |     getPlugins(): Map<string, HookPlugin> {
504 |         return new Map(this.plugins);
505 |     }
506 | 
507 |     /**
508 |      * 获取插件
509 |      */
510 |     getPlugin(name: string): HookPlugin | undefined {
511 |         return this.plugins.get(name);
512 |     }
513 | 
514 |     /**
515 |      * 注册默认插件集合
516 |      */
517 |     registerDefaultPlugins(agent: HookAgent): void {
518 |         this.registerPlugin('logging', new LoggingHookPlugin(), agent);
519 |         this.registerPlugin('performance', new PerformanceHookPlugin(), agent);
520 |         this.registerPlugin('validation', new ValidationHookPlugin(), agent);
521 |         this.registerPlugin('statistics', new StatisticsHookPlugin(), agent);
522 |         this.registerPlugin('cache', new CacheHookPlugin(), agent);
523 |         
524 |         this.logger.info('Registered default plugins: logging, performance, validation, statistics, cache');
525 |     }
526 | }
