register(AgentHook.BEFORE_LLM_CALL, async (data: BeforeLLMCallData) => {
    const cacheKey = this.generateLLMCacheKey(data);
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.ttl) {
